"use client";
import { useEffect, useMemo, useState } from "react";
import type { UsageGraph } from "../../catalog-core/usage-graph.js";
import type { WiringException } from "../../catalog-core/wiring.js";

/** A graph and the wiring exceptions recorded against the same sources. */
export interface UsageData { readonly graph: UsageGraph; readonly exceptions?: readonly WiringException[] }

let loaded: Promise<UsageData | undefined> | undefined;

/**
 * The committed Foundry usage graph (`catalog/reports/usage-graph.json`, regenerated by `designer-library graph`)
 * and Foundry's committed wiring exceptions. They are the only things the Usage area loads at render (spec C5),
 * once and lazily, because the graph is large.
 */
export function loadCommittedUsage(): Promise<UsageData | undefined> {
  loaded ??= Promise.all([
    import("../../catalog/reports/usage-graph.json", { with: { type: "json" } }),
    import("../../catalog/rules/wiring-exceptions.json", { with: { type: "json" } }),
  ]).then(([report, rules]) => {
    const graph = report.default as unknown as UsageGraph;
    const exceptions = (rules.default as unknown as { exceptions?: readonly WiringException[] }).exceptions;
    return graph.schemaVersion === 1 ? { graph, ...(exceptions ? { exceptions } : {}) } : undefined;
  }).catch(() => undefined);
  return loaded;
}

/**
 * The host's graph when it supplies one, else the committed graph once it has loaded. `enabled: false` loads
 * nothing, so a host that shows no usage never pays for the committed report.
 */
export function useUsageData(graph?: UsageGraph, enabled = true): UsageData | undefined {
  const [committed, setCommitted] = useState<UsageData | undefined>(undefined);
  useEffect(() => {
    if (graph || !enabled) return;
    let live = true;
    void loadCommittedUsage().then(value => { if (live) setCommitted(value); });
    return () => { live = false; };
  }, [graph, enabled]);
  const supplied = useMemo<UsageData | undefined>(() => graph ? { graph } : undefined, [graph]);
  return supplied ?? (enabled ? committed : undefined);
}
